				else_if = {
					limit = { is_hive_empire = yes }
					text = shroud.first_contact.1.desc.hive
				}
				else = {
					text = shroud.first_contact.1.desc.default
				}
			}
		}
	}

	is_triggered_only = yes
	diplomatic = yes
	force_open = yes

	picture_event_data = {
		portrait = shroud1
		room = shroud_room
	}

	show_sound = {
		trigger = { is_robot_empire = yes }
		sound = event_psionic_robot
	}
	show_sound = {
		trigger = { is_robot_empire = no }
		sound = event_psionic
	}

	immediate = {
		set_country_flag = shroud_first_contact_the_composer_of_strands
		if = {
			limit = { has_country_flag = shroud_first_major_contact_3 }
			remove_country_flag = shroud_first_major_contact_3
			set_country_flag = shroud_first_major_contact_4
		}
		else_if = {
			limit = { has_country_flag = shroud_first_major_contact_2 }
			remove_country_flag = shroud_first_major_contact_2
			set_country_flag = shroud_first_major_contact_3
		}
		else_if = {
			limit = { has_country_flag = shroud_first_major_contact_1 }
