			set_country_flag = shroud_first_major_contact_2
		}
		else = {
			set_country_flag = shroud_first_major_contact_1
		}
	}

	after = {
		remove_country_flag = shroud_first_contact_the_composer_of_strands
	}

	option = {
		name = shroud.first_contact.prompt
